.article-paragraph {
  text-align: justify;
  text-align-last: start; /* Options: start, end, center, justify (default) */
  margin-bottom: 1em;
  font-family: "Merriweather", serif; /* Example web font */
  font-size: 1.125rem;
  line-height: 1.6;
  max-width: 65ch; /* Optimal line length for readability */
  color: #333;
  /* Adding soft hyphens for better justification, if not globally applied */
  -webkit-hyphens: auto;
  -ms-hyphens: auto;
  hyphens: auto;
  word-break: normal;
}
